<template>
  <section class="archive-workspace">
    <header class="archive-hero"><div><span>出租房源资料库</span><h2>下架房源管理</h2><p>集中查看已下架房源的业主、租约、附件及维修历史，需要时可沿用原资料重新上架。</p></div><div class="archive-note"><b>资料完整保留</b><small>下架后仍可查看历史并重新上架</small></div></header>
    <div class="archive-metrics"><article><small>已下架房源</small><strong>{{ summary.total||0 }} <i>套</i></strong><span>当前已下架总数</span></article><article><small>本月下架</small><strong>{{ summary.thisMonth||0 }} <i>套</i></strong><span>本月下架房源</span></article><article><small>已有附件</small><strong>{{ summary.withDocuments||0 }} <i>套</i></strong><span>资料可继续查阅</span></article><article><small>可重新上架</small><strong>{{ summary.canRelist||0 }} <i>套</i></strong><span>目前空置且可重新招租</span></article></div>
    <div class="archive-toolbar"><label><span>⌕</span><input v-model.trim="keyword" placeholder="搜索建案、单位、业主或电话" @keyup.enter="reloadFirst"></label><select v-model="reasonCode" @change="reloadFirst"><option value="">全部下架原因</option><option v-for="item in reasons" :key="item.value" :value="item.value">{{ item.label }}</option></select><button type="button" @click="reloadFirst">查询</button><button type="button" class="plain" @click="reset">清除筛选</button></div>
    <div class="archive-panel"><div class="archive-panel-head"><div><h3>下架房源列表</h3><p>共 {{ page.totalRows||0 }} 套；点击“查看资料”可浏览对应房产的完整档案。</p></div></div><div v-if="loading" class="archive-state">正在载入下架房源……</div><div v-else-if="error" class="archive-state error"><b>资料载入失败</b><span>{{ error }}</span><button type="button" @click="load">重新载入</button></div><div v-else-if="!rows.length" class="archive-empty"><b>暂无下架房源</b><span>从“租房流程”下架后，房源会连同历史资料出现在这里。</span></div><div v-else class="archive-table-wrap"><table><thead><tr><th>出租房源</th><th>业主</th><th>下架信息</th><th>历史资料</th><th>当前出租状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in rows" :key="item.unitId"><td><b>{{ item.projectName }} · {{ item.unitNo }}</b><small>{{ [item.city,item.building,item.floorNo].filter(Boolean).join(' · ')||'资料待补充' }}</small></td><td><b>{{ item.ownerName }}</b><small>{{ item.ownerPhone||'未填写电话' }}</small></td><td><span class="reason-tag">{{ reasonLabel(item.reasonCode) }}</span><small>{{ dateTime(item.offMarketAt) }} · {{ item.offMarketByName }}</small><em v-if="item.note">{{ item.note }}</em></td><td><div class="archive-counts"><span><b>{{ item.leaseCount }}</b>租约</span><span><b>{{ item.documentCount }}</b>附件</span><span><b>{{ item.maintenanceCount }}</b>维修</span></div></td><td><span class="status-tag">{{ listingLabel(item.listingStatus) }}</span></td><td><div class="archive-actions"><button type="button" class="plain" @click="view(item)">查看资料</button><button type="button" class="plain" @click="showHistory(item)">上下架记录</button><button v-if="pageBridge.canManageCurrentAdminModule" type="button" @click="openRelist(item)">重新上架招租</button></div></td></tr></tbody></table></div><footer v-if="page.totalPages>1" class="archive-pager"><span>第 {{ page.page }} / {{ page.totalPages }} 页</span><button :disabled="page.page<=1" @click="go(page.page-1)">上一页</button><button :disabled="page.page>=page.totalPages" @click="go(page.page+1)">下一页</button></footer></div>
    <dialog ref="relistDialog" class="archive-dialog"><form method="dialog" @submit.prevent="confirmRelist"><header><div><small>恢复招租</small><h3>重新上架出租房源</h3></div><button type="button" @click="closeRelist">×</button></header><section><div class="selected-archive"><b>{{ selected?.projectName }} · {{ selected?.unitNo }}</b><span>{{ selected?.ownerName }}</span></div><p>重新上架后，该房源会恢复招租；房产资产状态和全部历史资料不会改变。</p><label>重新上架备注（可选）<textarea v-model.trim="relistNote" rows="3" maxlength="500" placeholder="例如：业主确认恢复招租"></textarea></label><p v-if="dialogError" class="dialog-error">{{ dialogError }}</p></section><footer><button type="button" class="plain" @click="closeRelist">取消</button><button :disabled="saving">{{ saving?'处理中…':'确认重新上架' }}</button></footer></form></dialog>
    <dialog ref="historyDialog" class="archive-dialog"><div class="history-shell"><header><div><small>出租房源上下架记录</small><h3>{{ selected?.projectName }} · {{ selected?.unitNo }}</h3></div><button type="button" @click="$refs.historyDialog.close()">×</button></header><section><div v-if="historyLoading" class="archive-state">正在载入记录……</div><ol v-else class="history-list"><li v-for="item in history" :key="item.id"><i :class="item.action"></i><div><b>{{ item.action==='relisted'?'重新上架招租':'下架房源' }}</b><span>{{ item.changedByName }} · {{ dateTime(item.createdAt) }}</span><small>{{ item.reasonCode?reasonLabel(item.reasonCode):'' }}{{ item.note?` · ${item.note}`:'' }}</small></div></li></ol></section></div></dialog>
  </section>
</template>
<script>
import { fetchAdminOffMarketProperties,fetchAdminPropertyManagementHistory,relistAdminProperty } from '../services/propertyApi';import { navigate } from '../router';
export default{inject:{pageBridge:{from:'page'}},data(){return{rows:[],page:{page:1,pageSize:10,totalRows:0,totalPages:1},summary:{},keyword:'',reasonCode:'',loading:false,error:'',selected:null,relistNote:'',saving:false,dialogError:'',history:[],historyLoading:false,reasons:[{value:'OWNER_REQUEST',label:'业主要求下架'},{value:'TEMPORARY_HOLD',label:'暂缓出租'},{value:'RENOVATION',label:'装修或维修'},{value:'SOLD_OR_TRANSFERRED',label:'出售或转让'},{value:'DATA_CLEANUP',label:'资料整理'},{value:'OTHER',label:'其他原因'}]};},mounted(){this.load();},methods:{async load(){this.loading=true;this.error='';try{const d=await fetchAdminOffMarketProperties({page:this.page.page,pageSize:this.page.pageSize,keyword:this.keyword,reasonCode:this.reasonCode});this.rows=d.rows||[];this.page=d.page||this.page;this.summary=d.summary||{};}catch(e){this.error=e.message||'下架房源载入失败';}finally{this.loading=false;}},reloadFirst(){this.page.page=1;this.load();},reset(){this.keyword='';this.reasonCode='';this.reloadFirst();},go(v){this.page.page=v;this.load();},reasonLabel(v){return this.reasons.find(x=>x.value===v)?.label||v||'未说明';},listingLabel(v){return({available:'可出租',reserved:'已预留',rented:'出租中',occupied:'已入住',inactive:'停用',sold:'已出售'})[v]||v||'未设置';},dateTime(v){return v?String(v).replace('T',' ').slice(0,16):'—';},view(i){navigate(`/admin/off-market-rentals/${i.unitId}`);},openRelist(i){this.selected=i;this.relistNote='';this.dialogError='';this.$refs.relistDialog.showModal();},closeRelist(){this.$refs.relistDialog?.close();},async confirmRelist(){if(!this.selected)return;this.saving=true;this.dialogError='';try{await relistAdminProperty(this.selected.unitId,{note:this.relistNote});this.closeRelist();this.pageBridge.showToast('出租房源已重新上架，原有资料完整保留');await this.load();}catch(e){this.dialogError=e.message||'重新上架失败';}finally{this.saving=false;}},async showHistory(i){this.selected=i;this.history=[];this.historyLoading=true;this.$refs.historyDialog.showModal();try{this.history=await fetchAdminPropertyManagementHistory(i.unitId)||[];}finally{this.historyLoading=false;}}}};
</script>
<style scoped>
