e-table-wrap table{width:100%;border-collapse:collapse}.archive-table-wrap th{padding:13px 14px;text-align:left;background:#f3f8fa;color:#47657c;white-space:nowrap}.archive-table-wrap td{padding:14px;border-top:1px solid #e2ebee;vertical-align:top}.archive-table-wrap td b,.archive-table-wrap td small,.archive-table-wrap td em{display:block}.archive-table-wrap td small{margin-top:5px;color:#71889a}.archive-table-wrap td em{max-width:260px;margin-top:7px;color:#536c7e;font-style:normal}.reason-tag,.status-tag{display:inline-block;padding:4px 9px;border-radius:999px;background:#fff4d7;color:#9a6500;font-size:12px}.status-tag{background:#edf7f8;color:#087d83}.archive-counts{display:flex;gap:12px}.archive-counts span{font-size:12px;color:#73899b}.archive-counts b{font-size:17px;color:#133e60}.archive-actions{display:flex;gap:6px;flex-wrap:wrap;min-width:230px}.archive-actions button{min-height:34px;padding:0 10px;font-size:12px}.archive-state,.archive-empty{display:grid;place-items:center;gap:8px;min-height:220px;color:#70889a}.archive-state.error,.dialog-error{color:#d54b42}.archive-pager{display:flex;justify-content:flex-end;align-items:center;gap:8px;padding:12px 16px;border-top:1px solid #e1eaed}.archive-dialog{width:min(620px,calc(100vw - 36px));padding:0;border:0;border-radius:14px}.archive-dialog::backdrop{background:#18374799}.archive-dialog header{display:flex;justify-content:space-between;padding:20px 22px;border-bottom:1px solid #e0eaed}.archive-dialog h3{margin:4px 0 0}.archive-dialog header button{min-height:32px;padding:0 10px;background:#fff;color:#d7463d;border-color:#efb3af;font-size:22px}.archive-dialog section{padding:20px 22px}.selected-archive{display:flex;justify-content:space-between;padding:14px;background:#eef8f8;border-radius:9px}.archive-dialog label{display:grid;gap:7px;margin-top:18px;font-weight:700}.archive-dialog textarea{padding:11px;border:1px solid #cadde4;border-radius:8px}.archive-dialog footer{display:flex;justify-content:flex-end;gap:8px;padding:14px 22px;background:#f6f9fa}.history-list{list-style:none;margin:0;padding:0}.history-list li{display:flex;gap:12px;padding:14px 0;border-bottom:1px solid #e2eaed}.history-list i{width:12px;height:12px;margin-top:5px;border-radius:50%;background:#e6aa00}.history-list i.relisted{background:#079da3}.history-list span,.history-list small{display:block;margin-top:4px;color:#71889a}@media(max-width:900px){.archive-metrics{grid-template-columns:repeat(2,1fr)}.archive-hero{align-items:flex-start;flex-direction:column}.archive-toolbar{flex-wrap:wrap}.archive-toolbar label{flex-basis:100%}}@media(max-width:560px){.archive-metrics{grid-template-columns:1fr}.archive-workspace{padding:0 10px}}
</style>
